// src/pages/Splash.js

import { useNavigate } from "react-router-dom";

function Splash() {
  const navigate = useNavigate();

  return (
    <div className="splash-page">
      <div>
        <div className="splash-logo">
          READLY
        </div>

        <div className="splash-sub">
          읽고, 쓰고, 함께 나누다
        </div>
      </div>

      <div className="splash-btn-wrap">
        <button
          className="start-btn"
          onClick={() =>
            navigate("/login")
          }
        >
          시작하기
        </button>
      </div>
    </div>
  );
}

export default Splash;
